//
// This is only a SKELETON file for the 'BookStore' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const BOOK_PRICE = 800;
const DISCOUNTS = {
  1: 0,
  2: 0.05,
  3: 0.1,
  4: 0.2,
  5: 0.25,
};

const groupPrice = (size) =>
  size * BOOK_PRICE - Math.round(size * BOOK_PRICE * DISCOUNTS[size]);

export const cost = (books) => {
  const counts = [0, 0, 0, 0, 0];

  for (const book of books) {
    counts[book - 1] += 1;
  }

  const groups = [];

  while (counts.some((count) => count > 0)) {
    let groupSize = 0;

    for (let i = 0; i < counts.length; i += 1) {
      if (counts[i] > 0) {
        counts[i] -= 1;
        groupSize += 1;
      }
    }

    groups.push(groupSize);
  }

  // A group of 5 plus a group of 3 is more expensive than two groups of 4.
  // Replace as many such pairs as possible.
  let fives = groups.filter((size) => size === 5).length;
  let threes = groups.filter((size) => size === 3).length;

  while (fives > 0 && threes > 0) {
    groups[groups.indexOf(5)] = 4;
    groups[groups.indexOf(3)] = 4;
    fives -= 1;
    threes -= 1;
  }

  return groups.reduce((total, size) => total + groupPrice(size), 0);
};
